import {unzipSync,strFromU8} from './vendor/fflate.js';
import {parsePackage,checkMetadataSize,MAX_ENTRIES} from './ocw-import.js';
self.onmessage=event=>{try{let total=0,count=0;const records=Object.create(null);const files=unzipSync(new Uint8Array(event.data),{filter:file=>{if(++count>MAX_ENTRIES)throw Error('This ZIP has too many files.');if(!/data\.json$/i.test(file.name)||file.name.includes('__MACOSX/'))return false;total+=file.originalSize;checkMetadataSize(file.originalSize,total);return true;}});for(const [name,data] of Object.entries(files)){try{records[name]=JSON.parse(strFromU8(data));}catch{throw Error('Could not read metadata file: '+name);}}self.postMessage({course:parsePackage(records)});}catch(e){self.postMessage({error:e.message||'Could not read this OCW ZIP file.'});}};
